declarations.code:
template <class I>

concept bidirectional_iterator =

    std::forward_iterator<I> &&

    std::derived_from</*ITER_CONCEPT*/<I>, std::bidirectional_iterator_tag> &&

    requires(I i) {
        { --i } -> std::same_as<I &>;

        { i-- } -> std::same_as<I>;
    };

examples.code:
#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::bidirectional_iterator<int *>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
